jsLib:
// 获取变量
function hqbl(key) {
  // LoginInfo：密钥、字体、半屏、屏幕宽度、颜色、自定义气泡
  // Variable：平台、域名、自订、定制、评论、段评、热评、本章说、气泡样式
  const { source } = this;
  try {
    let config = {};
    if (/(密钥|字体|屏|颜色|自定义)/.test(key)) {
      config = JSON.parse(source.getLoginInfo());
    } else {
      config = JSON.parse(source.getVariable());
    }
    return config[key] || "";
  } catch (e) { return ""; }
}

// 刷新发现
function sxfx(key, value) {
  const { java, source } = this;
  let config = {};
  try {
    config = JSON.parse(source.getVariable());
  } catch (e) { }
  config[key] = value;
  source.setVariable(JSON.stringify(config, null, 2));
  java.refreshExplore();
  java.toast(`已切换${value}`);
}

// 获取域名
function zdyu() {
  let domain = this.hqbl("域名") || "域名一";

  const domainMap = {
    "域名一": "gxom.lol",
    "域名二": "gxom.mom",
  };
  return domainMap[domain];
}

// 设备类型
function deviceType() {
  try {
    return !!java.deviceID();
  } catch (e) {
    return false;
  }
}

// 应用类型
function appType() {
  try {
    if (Boolean(java.deviceID())) {
      return "srcread";
    } else { return "qiread"; }
  } catch (e) {
    let id = this.device1();
    if (id.length == 32) {
      return "qysg";
    } else if (id.length == 36) {
      return "qiread";
    } else {
      return "lyc";
    }
  }
}

// 主题风格
// 0跟随系统 1亮色 2暗色 3墨水屏
function theme() {
  try {
    return this.java.getThemeMode();
  } catch (e) {
    let isNight = this.hqbl("夜间");
    return isNight == "已开" ? "2" : "1";
  }
}

// 获取平台
function zdym() {
  let domain = this.hqbl("平台");
  if (!domain) domain = "番茄";

  const domainMap = {
    "番茄": "fanqie",
    "七猫": "qimao",
    "书旗": "shuqi",
    "起点": "qidian",
    "喜马拉雅": "xmly"
  };
  let subDomain = domainMap[domain];
  return "https://" + subDomain + "." + this.zdyu();
}

// 用户密钥（按正文接口返回浅殇或柒默密钥）
function zdmy() {
  const api = this.hqbl("正文接口") || "浅殇";
  if (api == "柒默") return this.hqbl("柒默密钥");
  return this.hqbl("浅殇密钥");
}

// 获取设备
function device1() {
  return String(this.java.androidId());
}

// 特权密钥
function jsmy() {
  let c = this.cookie.getCookie(zdym.call(this)) || "";
  return c.match(/qdkey=([^;]*)/)?.[1] || "";
}

// 阅文GUID
function ywguid() {
  let ywguid = String(this.cookie.getCookie("https://m.qidian.com").match(/ywguid=([^;]*)/)?.[1] || '');
  return ywguid;
}

// 阅文key
function ywkey() {
  let ywkey = String(this.cookie.getCookie("https://m.qidian.com").match(/ywkey=([^;]*)/)?.[1] || '');
  return ywkey;
}

// 用户中心
function yhzx() {
  this.java.toast("电报群获取方法");
}

// 柒默用户 tag
function qimoTag() {
  try {
    return this.cache.get("userTag") || "";
  } catch (e) {
    return "";
  }
}

// 柒默 API URL 附加 tag
function appendQimoTag(url) {
  const tag = qimoTag.call(this);
  if (tag) url += `&tag=${encodeURIComponent(tag)}`;
  return url;
}

// 购买章节
function showBuyChapter(bookId, chapterId, timestamp) {
  const api = this.hqbl("正文接口") || "浅殇";
  if (api == "柒默") {
    try {
      let buyUrl = `https://qdgo.qimo.host/api/content?bookId=${bookId}&chapterId=${chapterId}&buy=1`;
      buyUrl = appendQimoTag.call(this, buyUrl);
      const token = this.zdmy();
      const options = token ? { headers: { Authorization: `Bearer ${token}` } } : {};
      const resp = this.java.ajax(`${buyUrl},${JSON.stringify(options)}`);
      const jsonData = JSON.parse(resp);
      if (jsonData.code === 0 || jsonData.Result === 0) {
        this.java.toast("购买成功，请手动刷新章节");
      } else if (jsonData.Result === -60001) {
        this.java.toast("购买失败，余额不足");
      } else {
        this.java.toast("购买失败：" + (jsonData.msg ?? jsonData.error ?? jsonData.Message));
      }
    } catch (e) {
      this.java.toast("购买过程中发生错误：" + e.message);
    }
    return;
  }
  let radius = Number(this.hqbl("半屏圆角")) || 20;
  let height = Number(this.hqbl("半屏高度占比")) || 0.5;
  let url = `https://qidian.${this.zdyu()}/content.php?bookId=${bookId}&chapterId=${chapterId}&gm=1&ywkey=${this.ywkey()}&ywguid=${this.ywguid()}`;
  let config = JSON.stringify({ expandedCornersRadius: radius, heightPercentage: height });
  this.java.showBrowser(url, null, null, config);
}

// 起点正文数据
function getQdContentData(bookId, chapterId, rawUrl) {
  const { java } = this;
  const api = this.hqbl("正文接口") || "浅殇";
  const zd = this.hqbl("自订") || "已关";
  const dz = this.hqbl("定制") || "已关";

  if (api == "柒默") {
    let url = `https://qdgo.qimo.host/api/content?bookId=${bookId}&chapterId=${chapterId}`;
    if (zd == "已开") url += "&buy=1";
    url = appendQimoTag.call(this, url);
    const token = this.zdmy();
    const options = token ? { headers: { Authorization: `Bearer ${token}` } } : {};
    try {
      const qimoResp = java.ajax(`${url},${JSON.stringify(options)}`);
      const qimoData = JSON.parse(qimoResp);
      if ((qimoData.code === -4402 && zd !== "已开") || qimoData.Result === -100020) {
        return { content: "", needBuy: true, error: "" };
      }
      let content = qimoData.content || "";
      if (!content) {
        if (qimoData.code !== 0 && qimoData.Result !== 0) {
          return { content: "", needBuy: false, error: qimoData.msg ?? qimoData.error ?? qimoData.Message ?? "获取失败" };
        }
        return { content: "", needBuy: false, error: "章节内容为空" };
      }
      return { content, needBuy: false, error: "" };
    } catch (e) {
      return { content: "", needBuy: false, error: e.message };
    }
  }

  let url = rawUrl;
  if (dz == "已开") {
    url = `${url}&pt=yy&zdkey=${this.zdmy()}&device=${this.device1()} `;
  } else if (zd == "已开") {
    url = `${url}&pt=yy&key=${this.zdmy()}&device=${this.device1()}&zd=1&ywkey=${this.ywkey()}&ywgid=${this.ywguid()}`;
  } else {
    url = `${url}&pt=yy&key=${this.zdmy()}&device=${this.device1()}`;
  }
  try {
    const qsResp = java.ajax(url);
    const qsData = JSON.parse(qsResp);
    let content = qsData?.data?.content ?? "";
    if (content === "触发防盗") {
      return { content: "", needBuy: true, error: "" };
    }
    return { content, needBuy: false, error: "" };
  } catch (e) {
    return { content: "", needBuy: false, error: e.message };
  }
}

// 起点未购章节购买 UI（源阅）
function createQdBuyContentSrcRead(bookId, chapterId) {
  const { java } = this;
  const svgString = createGodCommentSvg.call(this, { Content: "点击购买本章" });
  const base64Svg = java.base64Encode(svgString);
  const api = this.hqbl("正文接口") || "浅殇";
  if (api == "柒默") {
    const inner = createQdBuyContent.call(this, bookId, chapterId);
    return `<div rs-native>${inner}</div>`;
  }
  let url = `https://qidian.${this.zdyu()}/content.php?bookId=${bookId}&chapterId=${chapterId}&gm=1&ywkey=${this.ywkey()}&ywguid=${this.ywguid()}&ms=${this.theme()}`;
  return `<div rs-native>未购章节\n<img src="data:image/svg+xml;base64,${base64Svg}" onClick="java.startBrowser('${url}','购买本章')"/> </div>`;
}

// 起点未购章节购买 UI
function createQdBuyContent(bookId, chapterId) {
  const { java } = this;
  const svgString = createGodCommentSvg.call(this, { Content: "点击购买本章" });
  const base64Svg = java.base64Encode(svgString);
  const timestamp = Date.now() + "";
  return `未购章节\n<img src="data:image/svg+xml;base64,${base64Svg},{"style":"FULL","type":"god","click":"showBuyChapter('${bookId}','${chapterId}','${timestamp}')"}">`;
}

// 转义符号
function escapeXml(s) {
  return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");
}

