  });
  return res;
}

// 字素切分（近似）：按码点切分后，将 ZWJ / 变体选择符 / 肤色修饰 / 组合记号 / 区域指示符对合并进前一个 token
// 不依赖 Intl.Segmenter（Legado/Rhino 可能不支持），避免拆散代理对与组合 emoji
function toGraphemes(str) {
  let arr = Array.from(String(str || ""));
  let out = [];
  for (let i = 0; i < arr.length; i++) {
    let cp = arr[i];
    let code = cp.codePointAt(0);
    let combining =
      code === 0x200D ||                     // ZWJ
      (code >= 0xFE00 && code <= 0xFE0F) ||   // 变体选择符
      (code >= 0x1F3FB && code <= 0x1F3FF) || // 肤色修饰
      (code >= 0x0300 && code <= 0x036F) ||   // 组合变音记号
      (code >= 0x20D0 && code <= 0x20FF);     // 组合符号记号
    let prev = out.length ? out[out.length - 1] : "";
    let prevEndsZWJ = prev && prev.charCodeAt(prev.length - 1) === 0x200D;
    let prevIsLoneRI = prev.length === 2 && prev.codePointAt(0) >= 0x1F1E6 && prev.codePointAt(0) <= 0x1F1FF;
    let curIsRI = code >= 0x1F1E6 && code <= 0x1F1FF;
    if (out.length && (combining || prevEndsZWJ || (prevIsLoneRI && curIsRI))) {
      out[out.length - 1] += cp;
    } else {
      out.push(cp);
    }
  }
  return out;
}

// 字素显示宽度：emoji 记 1.25（彩色 emoji 前进宽度大于 1em），CJK/假名/谚文/全角 记 1，其余(ASCII/拉丁/半角) 记 0.5
function graphemeWidth(g) {
  let code = g.codePointAt(0);
  // emoji / 象形符 / 常用符号
  if (
    (code >= 0x1F000 && code <= 0x1FAFF) ||
    (code >= 0x2600 && code <= 0x27BF) ||
    (code >= 0x2B00 && code <= 0x2BFF) ||
    code === 0x2764 || code === 0x203C || code === 0x2049
  ) return 1.25;
  // CJK / 假名 / 谚文 / 全角 / 扩展区
  if (
    (code >= 0x1100 && code <= 0x115F) ||   // 谚文字母
    (code >= 0x2E80 && code <= 0x303E) ||   // CJK 部首 / 符号
    (code >= 0x3041 && code <= 0x33FF) ||   // 假名 / CJK 符号
    (code >= 0x3400 && code <= 0x4DBF) ||   // CJK 扩展 A
    (code >= 0x4E00 && code <= 0x9FFF) ||   // CJK 统一
    (code >= 0xA000 && code <= 0xA4CF) ||   // 彝文
    (code >= 0xAC00 && code <= 0xD7A3) ||   // 谚文音节
    (code >= 0xF900 && code <= 0xFAFF) ||   // CJK 兼容
    (code >= 0xFE30 && code <= 0xFE4F) ||   // CJK 兼容形式
    (code >= 0xFF00 && code <= 0xFF60) ||   // 全角
    (code >= 0xFFE0 && code <= 0xFFE6) ||   // 全角符号
    (code >= 0x20000)                       // CJK 扩展 B+
  ) return 1;
  return 0.5;
}

// 按视觉宽度分行：firstLineWidth 控制首行宽度（用于避开徽标），其余行用 maxWidth
function wrapByWidth(text, maxWidth, firstLineWidth) {
  let graphemes = toGraphemes(text);
  let lines = [];
  let cur = "", curW = 0;
  let limit = firstLineWidth || maxWidth;
  for (let i = 0; i < graphemes.length; i++) {
    let g = graphemes[i];
    let w = graphemeWidth(g);
    if (cur && curW + w > limit) {
      lines.push(cur);
      cur = "";
      curW = 0;
      limit = maxWidth;
    }
    cur += g;
    curW += w;
  }
  if (cur) lines.push(cur);
  return lines;
}

// 字素安全截断到 maxLines 行，超出时末行去掉一个字素并追加省略号
function truncateLines(lines, maxLines) {
  if (lines.length <= maxLines) return lines;
  let shown = lines.slice(0, maxLines);
  let last = toGraphemes(shown[maxLines - 1]);
  if (last.length > 0) last.pop();
  shown[maxLines - 1] = last.join("") + "…";
  return shown;
}

// 源阅分割正文
function splitContentSrcRead(content) {
  return content.replace(/<p>/g, "").replace(/<\/p>/g, "\n").split("\n").map(x => x.trim()).filter(Boolean);
}

// 通用分割正文
function splitContent(content) {
  return content.replace(/(<img[^>]*?>)<\/p>/g, "$1</p>").split("</p>");
}

// 分割段落
function splitParagraphs(content) {
  let cleanedContent = (content || '').replace(/\r/g, '').trim().split('\n');
  let paragraphs = [null];
  for (let i = 0; i < cleanedContent.length; i++) {
    paragraphs[i + 1] = cleanedContent[i].trim();
  }
  return paragraphs;
}

