// 神评图片
function createGodCommentSvg(godItem) {
  let font = escapeXml(this.hqbl("评论字体") || "sans-serif");
  let isFold = this.hqbl("热评样式") != "展开"; // 未设置默认折叠，仅显式“展开”才多行

  let themeMode = this.theme();
  let fontColor = this.hqbl("评论颜色") || themeMode == "2" ? "#EEEEEE" : "#000000";
  let badgeColor = themeMode == "3" ? "#000000" : "#FF4444";

  const width = this.hqbl("屏幕宽度") || 1000;
  const height = 120, padX = 32, badgeWidth = 140, badgeHeight = 56;
  let centerY = height / 2 + 15, currentY = height;

  let contentText = godItem.text || godItem.Content || godItem.content || "";
  let raw = replaceEmoji(contentText);

  // 按像素预算计算行宽：右内边距 = 徽标左内边距(padX)；emoji 由 graphemeWidth(1.25) 加权防溢出
  const gFont = 52, rightPad = padX, firstLineX = padX + badgeWidth + 10;
  const firstLineWidth = (width - rightPad - firstLineX) / gFont;  // 首行(徽标右侧)
  const fullLineWidth = (width - rightPad - padX) / gFont;          // 后续行

  let rawGraphemes = toGraphemes(raw);
  let rawWidth = 0;
  for (let i = 0; i < rawGraphemes.length; i++) rawWidth += graphemeWidth(rawGraphemes[i]);

  let svgStr = `<svg width="${width}" height="1" xmlns="http://www.w3.org/2000/svg">
bgFill Placeholder
<rect x="${padX}" y="${(height - badgeHeight) / 2}" width="${badgeWidth}" height="${badgeHeight}" rx="30" fill="${badgeColor}"/>
<text x="${padX + badgeWidth / 2}" y="${centerY - 2}" font-size="32" font-family="${font}" fill="#FFFFFF" text-anchor="middle" font-weight="bold">热评</text>
`;

  if (rawWidth <= firstLineWidth || isFold) {
    let display = raw;
    if (rawWidth > firstLineWidth) {
      let acc = "", accW = 0;
      for (let i = 0; i < rawGraphemes.length; i++) {
        let gw = graphemeWidth(rawGraphemes[i]);
        if (accW + gw > firstLineWidth - 1) break;
        acc += rawGraphemes[i];
        accW += gw;
      }
      display = acc + "...";
    }
    svgStr += `<text x="${firstLineX}" y="${centerY + 4}" font-size="52" font-family="${font}" fill="${fontColor}" font-weight="bold">${escapeXml(display)}</text>`;
  } else {
    let lines = wrapByWidth(raw, fullLineWidth, firstLineWidth);
    svgStr += `<text x="${firstLineX}" y="${centerY + 4}" font-size="52" font-family="${font}" fill="${fontColor}" font-weight="bold">${escapeXml(lines[0])}</text>`;
    for (let i = 1; i < lines.length; i++) {
      svgStr += `<text x="${padX}" y="${centerY + 4 + i * 68}" font-size="52" font-family="${font}" fill="${fontColor}" font-weight="bold">${escapeXml(lines[i])}</text>`;
    }
    currentY += (lines.length - 1) * 68;
  }

  let bgFill =
    themeMode == "3" ? `<rect x="0" y="0" width="${width}" height="${currentY}" rx="60" fill="#FFFFFF"/>
<rect x="2" y="2" width="${width - 4}" height="${currentY - 4}" rx="58" fill="none" stroke="#000000" stroke-width="4"/>` :
      themeMode == "2" ? `<rect width="100%" height="100%" fill="rgba(210,210,210,0.15)" rx="60"/>` :
        `<rect width="100%" height="100%" fill="rgba(0,0,0,0.15)" rx="60"/>`;

  svgStr = svgStr.replace(/height="1"/, `height="${currentY}"`).replace(/bgFill Placeholder/, bgFill);
  svgStr += `</svg>`;
  return svgStr;
}

// 番茄段评数据
function getFqIdeaData(bookId, chapterId) {
  try {
    let url = `https://fanqie.${this.zdyu()}/fqdlsj.php?item_id=${chapterId}&book_id=${bookId}`;
    let res = JSON.parse(this.java.ajax(url));
    return res?.data?.idea_data || {};
  } catch (e) { return {}; }
}

// 番茄神评数据
function getFqGodData(bookId, chapterId) {
  try {
    let url = `https://fanqie.${this.zdyu()}/spsj.php?item_id=${chapterId}&book_id=${bookId}`;
    let res = JSON.parse(this.java.ajax(url));
    return res?.data?.idea_data || {};
  } catch (e) { return {}; }
}

function showFqCmt(bookId, chapterId, paragraphId, version, timestamp) {
  let radius = Number(this.hqbl("半屏圆角")) || 20;
  let height = Number(this.hqbl("半屏高度占比")) || 0.5;
  let config = JSON.stringify({ expandedCornersRadius: radius, heightPercentage: height });
  let url = `https://fanqie.${this.zdyu()}/fqdlpl.php?item_id=${chapterId}&book_id=${bookId}&para=${paragraphId}&version=${version}&ms=${this.theme()}`;
  this.java.showBrowser(url, null, null, config);
}

// 番茄渲染评论
function fanqiegetComments(content, bookId, chapterId, version) {
  const { java, cache } = this;
  try {
    let paragraphs = splitContent.call(this, content);
    let dp = this.hqbl("段评") || "已开", rp = this.hqbl("热评") || "已开";

    if (dp == "已开") {
      let ideaData = getFqIdeaData.call(this, bookId, chapterId);
      Object.keys(ideaData).forEach(index => {
        if (paragraphs[index]) {
          cache.putMemory(`fq-${bookId}-${chapterId}-${index}-text`, paragraphs[index]);
          paragraphs[index] += `<img src="${createCommentSvg.call(this, ideaData[index].idea_count, bookId, chapterId, index, version, "fq")}">`;
        }
      });
    }
    if (rp == "已开") {
      let godData = getFqGodData.call(this, bookId, chapterId);
      Object.keys(godData).forEach(index => {
        let idx = parseInt(index);
        if (paragraphs[idx]) {
          let comments = godData[idx].show_out_comments || [];
          if (comments.length) {
            let svgString = createGodCommentSvg.call(this, comments[0]);
            let base64Svg = java.base64Encode(svgString), timeStamp = Date.now();
            paragraphs[idx] += `\n<img src="data:image/svg+xml;base64,${base64Svg},{"style":"FULL","type":"god","click":"showFqCmt('${bookId}','${chapterId}','${idx}','${version}','${timeStamp}')"}">`;
          }
        }
      });
    }
    return paragraphs.join("</p>");
  } catch (e) { return content; }
}

