function getQmIdeaData(bookId, chapterId) {
  // 兼容不同接口返回结构，并在首选域名不可用时自动切换备用域名。
  var javaObj = (this && this.java) || java;
  var preferred = "";
  try { preferred = (this && typeof this.zdyu === "function") ? this.zdyu() : ""; } catch (e) {}
  var domains = [];
  if (preferred) domains.push(preferred);
  if (preferred !== "gxom.lol") domains.push("gxom.lol");
  if (preferred !== "gxom.mom") domains.push("gxom.mom");

  function asList(value) {
    if (Array.isArray(value)) return value;
    if (value && typeof value === "object") {
      var keys = Object.keys(value);
      var out = [];
      keys.forEach(function (key) {
        var item = value[key];
        if (item && typeof item === "object") {
          if (item.__paragraphIndex == null && /^\d+$/.test(key)) {
            var copy = {};
            Object.keys(item).forEach(function (k) { copy[k] = item[k]; });
            copy.__paragraphIndex = Number(key);
            out.push(copy);
          } else out.push(item);
        }
      });
      return out;
    }
    return [];
  }

  for (var i = 0; i < domains.length; i++) {
    try {
      var url = "https://qimao." + domains[i] + "/qmdlsj.php?book_id=" + encodeURIComponent(bookId) + "&chapter_id=" + encodeURIComponent(chapterId);
      var response = javaObj.ajax(url);
      if (!response) continue;
      var parsed = (typeof response === "string") ? JSON.parse(response) : response;
      var bubbles = parsed && parsed.data && parsed.data.chapters && parsed.data.chapters[0] ? parsed.data.chapters[0].bubbles : null;
      if (bubbles == null && parsed && parsed.data) bubbles = parsed.data.bubbles;
      if (bubbles == null && parsed && parsed.chapters && parsed.chapters[0]) bubbles = parsed.chapters[0].bubbles;
      if (bubbles == null && parsed) bubbles = parsed.bubbles;
      var list = asList(bubbles);
      if (list.length) return list;
    } catch (e) {}
  }
  return [];
}

