    // 少数章节返回纯文本换行，而非 </p> 分段时，按换行兜底。
    if (paragraphs.length === 1 && paragraphs[0] && paragraphs[0].indexOf("</p>") < 0 && /\n/.test(paragraphs[0])) {
      paragraphs = paragraphs[0].split(/\r?\n/);
